      hrow.appendChild(img('l', 'data:image/png;base64,')); hrow.appendChild(htxt); hrow.appendChild(img('r', 'data:image/png;base64,')); hd.appendChild(hrow);
      refs.hdTpl = el('div', 'hdw'); refs.hdTpl.appendChild(hd);

